function state(){return{start:Number($q('qa-start').value),end:Number($q('qa-end').value),personIds:$q('qa-person').value?[$q('qa-person').value]:[],category:$q('qa-category').value,biblioTypes:[...$q('qa-biblio').querySelectorAll('input:checked')].map(i=>i.value),recentEnd:Number($q('qa-recent').value),minimum:$q('qa-minimum').value===''?null:Number($q('qa-minimum').value),concentration:$q('qa-concentration').value===''?null:Number($q('qa-concentration').value),sort,direction,reviewMode:$q('qa-mode').value,submission:Number($q('qa-submission').value)}}
