function doExport(action){if(state().reviewMode!=='automatic'&&(!window.AtlasReview||!AtlasReview.ready())){$q('qa-export-status').textContent='Aguardando as decisões salvas no servidor para exportar o cenário revisado.';window.addEventListener('atlas:reviews-ready',()=>actions[action](),{once:true});return}actions[action]()}
for(const [id,action]of Object.entries({'qa-word':'qual-word','qa-diagnosis-csv':'qual-diagnosis','qa-diagnosis-xlsx':'qual-spreadsheet','qa-detail-csv':'qual-details','qa-annual-csv':'qual-annual'}))$q(id).onclick=()=>{if(!openExport(action))doExport(action)};
function show(view){for(const [key,id]of Object.entries({general:'general',qualified:'qualified',orientations:'orientations'})){const selected=view===key;$q(id+'-view').hidden=!selected;$q('tab-'+id).setAttribute('aria-selected',String(selected))}if(view==='qualified')render();window.dispatchEvent(new CustomEvent('atlas:view',{detail:view}))}
$q('tab-general').onclick=()=>show('general');$q('tab-qualified').onclick=()=>show('qualified');$q('tab-orientations').onclick=()=>show('orientations');
for(const id of ['qa-mode','qa-person','qa-start','qa-end','qa-category','qa-recent','qa-minimum','qa-concentration'])$q(id).addEventListener('change',()=>{detailLimit=40;render()});
for(const id of ['qa-detail-person','qa-detail-state','qa-detail-category','qa-detail-year'])$q(id).addEventListener('change',()=>{detailLimit=40;renderDetails()});
$q('qa-more').onclick=()=>{detailLimit+=60;renderDetails()};
function setBiblio(keys){$q('qa-biblio').querySelectorAll('input').forEach(i=>i.checked=keys.includes(i.value));detailLimit=40;render()}
$q('qa-broad').onclick=()=>setBiblio(['artigo','livro','capitulo','anais']);$q('qa-strict').onclick=()=>setBiblio(['artigo','livro','capitulo']);
$q('qa-order').onchange=()=>{const value=$q('qa-order').value;if(value==='custom')return;[sort,direction]=value.split(':');render()};
window.addEventListener('atlas:cohort',()=>{detailLimit=40;render()});
$q('qa-reset').onclick=()=>{setState(C.defaults(Q));detailLimit=40;render()};
$q('qa-apcn').onclick=()=>{const y=Number($q('qa-submission').value);if(!Number.isInteger(y)||y<1905||y>2100){$q('qa-scope').textContent='Informe um ano de submissão válido.';return}$q('qa-start').value=y-5;$q('qa-end').value=y-1;render()};
$q('qa-ufg').onclick=()=>{$q('qa-start').value=Q.config.periodo_institucional.inicio;$q('qa-end').value=Q.config.periodo_institucional.fim;render()};
$q('qa-method').innerHTML='<p><a href="implementacao-classificacao.html" target="_blank" rel="noopener">Relatório de implementação, regras e testes ↗</a></p><p>'+Q.avisos.map(h).join('</p><p>')+'</p><p><a href="revisao-tecnica.html" target="_blank" rel="noopener">Consultar revisão de todos os registros técnicos ↗</a></p><p><strong>Revisão interpretativa:</strong> '+Q.estatisticas.registros_tecnicos_revisados+' de '+Q.estatisticas.registros_tecnicos+' registros técnicos examinados; '+Q.estatisticas.registros_tecnicos_sem_revisao+' novos/alterados com leitura pendente. A revisão interpreta a referência do Lattes, sem acesso à íntegra dos produtos nem validação do GT.</p><p><strong>Registros originais:</strong> '+Q.estatisticas.registros_originais+'; <strong>produtos únicos históricos:</strong> '+Q.estatisticas.produtos_unicos+'; <strong>repetições internas históricas consolidadas:</strong> '+Q.estatisticas.duplicatas_internas+'. Esses números históricos não representam o período filtrado.</p><p><strong>Regras:</strong> '+h(Q.versao_regras)+'. '+h(Q.regras.natureza)+'. '+h(Q.regras.ressalvas)+'</p><p><strong>Dez tipos específicos AU:</strong> '+Q.regras.tipos_tecnicos_au.map(h).join('; ')+'.</p><ul>'+Object.entries(Q.fontes).map(([key,s])=>'<li><a target="_blank" rel="noopener" href="'+h(s.url)+'">'+h(s.titulo)+'</a> — '+h(s.localizacao)+'; '+h(s.natureza)+'. '+h(s.uso)+'</li>').join('')+'</ul><p><strong>Deduplicação:</strong> correspondências fortes são consolidadas, mantendo todas as fontes. Anais, resumos, apresentações e produtos de natureza distinta não são fundidos apenas por título. Correspondências fracas são sinalizadas como possível duplicidade.</p>';
setState(C.defaults(Q));render();
const params=new URLSearchParams(location.search);if(params.get('view')==='qualified'){
 const raw=params.get('q');if(raw){try{const saved=JSON.parse(raw);setState({...C.defaults(Q),...saved.filters});render();for(const [key,id]of Object.entries({person:'qa-detail-person',state:'qa-detail-state',category:'qa-detail-category',year:'qa-detail-year'}))if(saved.detail?.[key]!==undefined)$q(id).value=saved.detail[key];renderDetails()}catch{}}
 show('qualified');const action=params.get('export');if(actions[action]&&window.self===window.top){const box=document.createElement('div');box.className='note';box.textContent='O download será iniciado. Se necessário, use o botão para repetir. ';const b=document.createElement('button');b.textContent='Baixar novamente';b.onclick=()=>doExport(action);box.append(b);$q('qualified-view').prepend(box);setTimeout(()=>doExport(action),350)}
}
window.AUDDiagnostic={data:Q,state,analysis:()=>analysis,detailItems,show,word,refresh:render};
